assert len(rows)==27,len(rows)
regimes={'oa-keter-dominion':5,'oa-communion-worlds':1,'17776-postmortal-america':2,'earth2150-ucs-robot-supported':1,'wyst-arrabus-egalist-provision':2,'implied-spaces-constructed-worlds':1,'riding-torch-convoy-abundance':2,'lady-mazes-teven-coronal':1,'mockingbird-robot-maintained-humans':5,'mizora-technological-resident-order':1}
for rid,updates,paragraph,facts in rows:
 old=D['societies'][rid];r=deepcopy(old);refs=r['source_ids']
 assert all(r['axis'][k] is None for k in updates),rid
 for key,(value,bounds,basis) in updates.items():r['axis'][key]=value;r['axis_assessment'][key]=assessment(value,bounds,'low',basis,refs)
 r['description']=old['description'].split('\n\n')[0]+'\n\n'+paragraph
 r.update(assessment_mode='best_guess',best_guess_axes=list(updates),qualification_basis='Earlier bounded source-based inclusion retained; individually supply missing coordinates as explicit editorial scenarios.',qualification_confidence='low',canon_facts=facts,editorial_assumptions=[v[2] for v in updates.values()])
 r['uncertainties']=[u for u in old['uncertainties'] if not any(t in u.lower() for t in ['remains unresolved','stays unresolved','cannot be considered complete','requires a separate editorial estimate'])]
 r['uncertainties']+=['New coordinate values are low-confidence scenarios rather than canonical statistics; original source limits remain.']+r['editorial_assumptions']
 if rid in regimes and r['record_type']!='zero_variant':
  primary=regimes[rid];prior=r['regime_primary'];r['regime_primary']=primary;r['regime_alternatives']=sorted((set(r['regime_alternatives'])|{prior})-{primary})
 r['review'].update(date=DATE,coordinate_ready=True,method='Individual completion using already bounded source evidence and explicit participation/control scenarios; no independent reviewer or new full-work reading')
 assert all(v is not None for v in r['axis'].values()),rid
 assert len(r['description'].split())>=110,rid
 changes.append(change(D,'societies',r))
write_revision(17,changes,'Complete twenty-seven earlier records, preserving all prior numeric axes and source access limits. Active person scopes, assigned short shifts, awake-only participation and human-derived controllers receive individual explanations.')
